package org.jlinalg.cli;
import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Explicit original CPU tree/root/pseudotime calls on declared coordinate inputs. */
final class ScfatesWorkflowRequest {
    private ScfatesWorkflowRequest() { }
    static final String EDITION="scfates-1.2.5_simpleppt-1.1.7";
    record Input(String id,String role,Path source,String format) {String key(){return id+"."+role;}}
    record Request(String edition,Path runtime,Path out,List<Map<String,Object>> analyses,List<Input> inputs,
                   long inputBytes,long outputBytes,int maximumFiles,int timeout,long auditOperations,
                   int maximumCells,int maximumComponents,int maximumNodes,long maximumMatrixCells,long pythonHashSeed) {
        Map<String,Object> worker(Map<String,Path> prepared)throws IOException {
            var cases=new ArrayList<Map<String,Object>>();for(var original:analyses){var analysis=new LinkedHashMap<>(original);var paths=new LinkedHashMap<String,String>();String id=text(original.get("id"));for(var input:inputs)if(input.id().equals(id))paths.put(input.role(),prepared.get(input.key()).toString());analysis.put("prepared",paths);cases.add(analysis);}
            return Map.of("schema_version",1,"edition",edition,"analyses",cases,"maximum_cells",maximumCells,"maximum_components",maximumComponents,"maximum_nodes",maximumNodes,"maximum_matrix_cells",maximumMatrixCells,"python_hash_seed",pythonHashSeed);
        }
    }
    static Request parse(Map<String,Object> root,Path parent)throws IOException {
        allowed(root,"schema_version","mode","edition","runtime","out","analyses","maximum_input_bytes","maximum_output_bytes","maximum_files","timeout_seconds","maximum_audit_operations","maximum_cells","maximum_components","maximum_nodes","maximum_matrix_cells","python_hash_seed");integer(root.get("schema_version"),1,1);require(text(root.get("mode")).equals("RUN"),"RUN executes analysis only; installation is separate");String edition=text(root.get("edition"));require(edition.equals(EDITION),"Only explicit scFates1.2.5/SimplePPT1.1.7 CPU coordinate workflows are bound; no paper edition is inferred");var analyses=new ArrayList<Map<String,Object>>();var inputs=new ArrayList<Input>();var ids=new HashSet<String>();
        for(Object raw:list(root.get("analyses"))){
            var a=object(raw);allowed(a,"id","method","input","weights","initialization","global_seed","tree","root","pseudotime","policies");String id=CellPhoneDbWorkflowRequest.id(a.get("id"));require(ids.add(id.toLowerCase(Locale.ROOT))&&analyses.size()<256,"Require1..256 unique portable case IDs, including case folding");require(text(a.get("method")).equals("tree-root-pseudotime"),"Declare the complete tree-root-pseudotime method");input(inputs,id,"coordinates",a.get("input"),parent);if(a.get("weights")!=null)input(inputs,id,"weights",a.get("weights"),parent);if(a.get("initialization")!=null)input(inputs,id,"initialization",a.get("initialization"),parent);integer(a.get("global_seed"),0,4294967295L);
            var tree=object(a.get("tree"));allowed(tree,"nodes","sigma","lambda","metric","nsteps","err_cut","seed");integer(tree.get("nodes"),2,10000);require(finite(tree.get("sigma"),0,Double.MAX_VALUE)>0,"Finite positive sigma required; no parameter repair");finite(tree.get("lambda"),0,Double.MAX_VALUE);require(text(tree.get("metric")).equals("euclidean"),"This validated CPU profile requires explicit Euclidean coordinates");integer(tree.get("nsteps"),1,1000000);finite(tree.get("err_cut"),0,Double.MAX_VALUE);integer(tree.get("seed"),0,4294967295L);
            var r=object(a.get("root"));allowed(r,"mode","node","values","tips_only","min_val");String mode=text(r.get("mode"));require(Set.of("node","obs").contains(mode),"Declare retained-node index or supplied observation values for root selection");bool(r.get("tips_only"));bool(r.get("min_val"));if(mode.equals("node")){integer(r.get("node"),0,9999);require(!r.containsKey("values"),"Node root must not contain an unused values request");}else{require(!r.containsKey("node"),"Observation root must not contain an unused node index");input(inputs,id,"root-values",r.get("values"),parent);}
            var pseudo=object(a.get("pseudotime"));allowed(pseudo,"n_map","n_jobs","seed");integer(pseudo.get("n_map"),1,1000);integer(pseudo.get("n_jobs"),1,64);integer(pseudo.get("seed"),0,4294967295L);var policies=object(a.get("policies"));allowed(policies,"nonconvergence","nonfinite_diagnostics","zero_assignment_rows","removed_nodes","missing_milestones");for(String name:List.of("nonconvergence","nonfinite_diagnostics","zero_assignment_rows","removed_nodes","missing_milestones"))require(Set.of("fail","retain-with-warning").contains(text(policies.get(name))),"Declare fail or retain-with-warning for "+name+"; warnings never repair an original exception");analyses.add(Collections.unmodifiableMap(new LinkedHashMap<>(a)));
        }
        require(!analyses.isEmpty(),"Require a complete nonempty analysis family");var keys=new HashSet<String>();for(var i:inputs)require(keys.add(i.key().toLowerCase(Locale.ROOT)),"Input member identity collision");return new Request(edition,resolve(parent,label(root.get("runtime"))),resolve(parent,label(root.get("out"))),List.copyOf(analyses),List.copyOf(inputs),number(root,"maximum_input_bytes",536870912,1,17179869184L),number(root,"maximum_output_bytes",4294967296L,1024,1099511627776L),Math.toIntExact(number(root,"maximum_files",100000,1,1000000)),Math.toIntExact(number(root,"timeout_seconds",1800,1,86400)),number(root,"maximum_audit_operations",2000000000L,1,10000000000000L),Math.toIntExact(number(root,"maximum_cells",100000,2,10000000)),Math.toIntExact(number(root,"maximum_components",256,1,4096)),Math.toIntExact(number(root,"maximum_nodes",4096,2,10000)),number(root,"maximum_matrix_cells",25000000,1,100000000),number(root,"python_hash_seed",0,0,4294967295L));
    }
    private static void input(List<Input> inputs,String id,String role,Object raw,Path parent)throws IOException {var value=object(raw);allowed(value,"path","format","source");String format=text(value.get("format"));require(Set.of("csv","tsv").contains(format),"Declare CSV/TSV numeric inputs; no pickle or suffix guessing");label(value.get("source"));inputs.add(new Input(id,role,resolve(parent,label(value.get("path"))),format));}
    static String data(Object raw)throws IOException {String value=text(raw);require(!value.isEmpty()&&value.codePoints().noneMatch(c->c<32&&c!=9&&c!=10&&c!=13||c==127||c>=0xd800&&c<=0xdfff),"Empty/unsupported-control/unpaired-surrogate data label; quoted TAB/CR/LF and exact Unicode remain unchanged");return value;}
    static void allowed(Map<String,Object> value,String... names)throws IOException {var keys=Set.of(names);for(String key:value.keySet())require(keys.contains(key),"Unknown scFates workflow field: "+key);}
}
